     * @param token The token address
     * @param recovered Amount recovered
     * @param reason Description of recovery (e.g., "emergency_unwind")
     */
    event EmergencyUnwindExecuted(
        uint256 indexed escrowId,
        address indexed token,
        uint256 recovered,
        bytes32 reason
    );
}
